S = "Hakeem Force Academy"
QS = [
 (S, "Out of 500 students, 340 are girls. What is the percentage of boys?", ["68%", "32%", "34%", "40%"], 1, "Boys = 500 - 340 = 160. Percentage of boys = 160 / 500 x 100 = 32%.", "The percentages of girls and boys always add up to 100%.", [994]),
 (S, "In a class of 450 students, 350 are male. What is the percentage of females?", ["33.33%", "22.22%", "28.57%", "25%"], 1, "Females = 450 - 350 = 100. Percentage = 100 / 450 x 100 = 22.22%.", "The male percentage in this class is 350 / 450 x 100 = 77.78%.", [2060]),
 (S, "In a class of 500 students, 350 were present. What is the percentage of absent students?", ["35%", "70%", "25%", "30%"], 3, "Absent = 500 - 350 = 150. Percentage = 150 / 500 x 100 = 30%.", "Present students are 70% of the class.", [2061]),
 (S, "Out of 4500 students, 340 are present. What is the percentage of absent students (to two decimal places)?", ["7.56%", "68%", "92.44%", "90.44%"], 2, "Absent = 4500 - 340 = 4160. Percentage = 4160 / 4500 x 100 = 92.44%.", "Present students are only 340 / 4500 x 100 = 7.56% of the total.", [2501]),
 (S, "Out of 4500 students, 3400 are present. What is the percentage of absent students (to two decimal places)?", ["75.56%", "24.44%", "68%", "32%"], 1, "Absent = 4500 - 3400 = 1100. Percentage = 1100 / 4500 x 100 = 24.44%.", "Present students are 3400 / 4500 x 100 = 75.56%.", [2502]),
 (S, "If 260 out of 500 students are present, what is the percentage of absent students?", ["52%", "48%", "40%", "260%"], 1, "Absent = 500 - 260 = 240. Percentage = 240 / 500 x 100 = 48%.", "Present students are 52% of the total.", [1924]),
 (S, "A class has 600 students and 420 are present. What is the percentage of absent students?", ["70%", "35%", "30%", "25%"], 2, "Absent = 600 - 420 = 180. Percentage = 180 / 600 x 100 = 30%.", "Present students are 70% of the class.", [1944]),
 (S, "In a school 500 students study and 320 are present. What is the percentage of absent students?", ["64%", "32%", "36%", "40%"], 2, "Absent = 500 - 320 = 180. Percentage = 180 / 500 x 100 = 36%.", "Present students are 64% of the total.", [2067]),
 (S, "In a class of 1000 students, 850 are present. What is the percentage of absentees?", ["15%", "85%", "10%", "20%"], 0, "Absent = 1000 - 850 = 150. Percentage = 150 / 1000 x 100 = 15%.", "Present students are 85% of the class.", [918]),
 (S, "What is 28% of 500?", ["120", "130", "150", "140"], 3, "28% of 500 = 28 / 100 x 500 = 140.", "10% of 500 is 50, so 28% is a little more than half of 250.", [2824]),
 (S, "The 3rd June Plan, which announced the partition of British India, was announced in which year?", ["1945", "1946", "1947", "1948"], 2, "Lord Mountbatten announced the plan on 3 June 1947. It decided the partition of India into India and Pakistan.", "It is also called the Mountbatten Plan, and India Independence Act followed in July 1947.", [3653]),
 (S, "Who was the third wife of the Holy Prophet Muhammad (PBUH), in order of marriage?", ["Hazrat Hafsa (RA)", "Hazrat Sawda (RA)", "Hazrat Aisha (RA)", "Hazrat Khadija (RA)"], 2, "In order of marriage the wives were Khadija, Sawda, then Aisha (RA). So Aisha (RA) was the third.", "Hazrat Aisha (RA) was the daughter of Hazrat Abu Bakr (RA); sources may differ on later order.", [4480]),
 (S, "If the 4th day of a month is Monday, what day will the 14th day be?", ["Wednesday", "Thursday", "Friday", "Tuesday"], 1, "From the 4th to the 14th is 10 days. 10 divided by 7 leaves 3, so Monday + 3 days = Thursday.", "Dates that differ by 7 fall on the same weekday.", [2002]),
 (S, "If the 15th day of a month is Monday, what day is the 4th of that month?", ["Wednesday", "Friday", "Thursday", "Sunday"], 2, "From the 4th to the 15th is 11 days. 11 divided by 7 leaves 4, so Monday - 4 days = Thursday.", "Going back 4 days is the same as going forward 3 days in a week.", [2008]),
 (S, "If the 5th day of a month is Sunday, what day is the 18th of the month?", ["Saturday", "Friday", "Sunday", "Monday"], 0, "From the 5th to the 18th is 13 days. 13 divided by 7 leaves 6, so Sunday + 6 days = Saturday.", "The 12th of this month would be Sunday too.", [2006]),
 (S, "If the 9th of a month is Sunday, what day is the 26th of the month?", ["Tuesday", "Thursday", "Monday", "Wednesday"], 3, "From the 9th to the 26th is 17 days. 17 divided by 7 leaves 3, so Sunday + 3 days = Wednesday.", "The 23rd of this month would be Sunday.", [2007]),
 (S, "If the 27th day of a month is Monday, what day will the 9th day be?", ["Wednesday", "Thursday", "Friday", "Tuesday"], 1, "From the 9th to the 27th is 18 days. 18 divided by 7 leaves 4, so Monday - 4 days = Thursday.", "The 13th would be Monday, as 27 - 14 = 13.", [237]),
 (S, "What is shown on the back of the Pakistani 5000 rupee note?", ["Badshahi Mosque", "Faisal Mosque, Islamabad", "Minar-e-Pakistan", "Mazar-e-Quaid"], 1, "The State Bank of Pakistan describes the back of the Rs 5000 note as showing the Faisal Mosque, Islamabad.", "The front of the note carries the portrait of Quaid-e-Azam Muhammad Ali Jinnah.", [1063, 2923, 3479]),
 (S, "Who was the fifth Mughal emperor of India?", ["Jahangir", "Akbar", "Aurangzeb", "Shah Jahan"], 3, "The order was Babur, Humayun, Akbar, Jahangir, then Shah Jahan. So Shah Jahan was fifth.", "Shah Jahan built the Taj Mahal, and Aurangzeb was the sixth emperor.", [4656, 1367]),
 (S, "What is the cube of 900?", ["810,000", "27,000,000", "729,000,000", "72,900,000"], 2, "9 x 9 x 9 = 729 and 100 x 100 x 100 = 1,000,000. So 900 cubed = 729,000,000.", "The square of 900 is 810,000.", [1091]),
 (S, "What is the square root of 900?", ["300", "30", "90", "45"], 1, "30 x 30 = 900, so the square root of 900 is 30.", "The square root of 9 is 3 and of 100 is 10, so 3 x 10 = 30.", [672]),
 (S, "How many peaks above 8000 metres are located in Pakistan?", ["3", "4", "5", "14"], 2, "Pakistan has five peaks above 8000 m: K2, Nanga Parbat, Gasherbrum I, Gasherbrum II and Broad Peak.", "The whole world has 14 peaks above 8000 m, and K2 at 8611 m is the second highest.", [1855, 42]),
 (S, "In the point (3, 4), what is the number 3 called?", ["Ordinate", "Abscissa", "Origin", "Quadrant"], 1, "In an ordered pair (x, y) the first number x is the abscissa. The second number y is the ordinate.", "The abscissa is measured along the x-axis.", [300]),
 (S, "What is the abscissa of a point also called?", ["y-coordinate", "x-coordinate", "Origin", "Slope"], 1, "The abscissa is the horizontal distance of a point, which is its x-coordinate.", "The y-coordinate is called the ordinate.", [2962]),
 (S, "What is the absolute value of a number?", ["Its square", "Its distance from zero, always non-negative", "Its reciprocal", "Its negative"], 1, "The absolute value is the distance of a number from zero on the number line, so it ignores the sign. For example |-5| = 5 and |5| = 5.", "The absolute value of zero is zero.", [629]),
 (S, "What is the value of absolute zero on the Celsius scale?", ["-100 degrees C", "0 degrees C", "-273.15 degrees C", "-373.15 degrees C"], 2, "Absolute zero is 0 Kelvin, which equals -273.15 degrees Celsius. It is the lowest possible temperature.", "On the Fahrenheit scale it is about -459.67 degrees.", [687]),
 (S, "What is a synonym of the word absolute?", ["Partial", "Complete", "Doubtful", "Weak"], 1, "Absolute means total or complete, without limit.", "An antonym of absolute is partial or relative.", [2863]),
 (S, "Where did Maulana Syed Abul Ala Maududi die?", ["Lahore", "Karachi", "Buffalo, New York", "London"], 2, "Maududi died in Buffalo, New York, USA, on 22 September 1979 while seeking medical treatment.", "He founded Jamaat-e-Islami in 1941 and was buried in Lahore.", [2118]),
 (S, "What is the antonym of the word abundant?", ["Plentiful", "Scarce", "Ample", "Rich"], 1, "Abundant means existing in large quantity. Its opposite is scarce, meaning in short supply.", "A synonym of abundant is plentiful.", [323]),
 (S, "Which element is the most abundant in the universe?", ["Oxygen", "Nitrogen", "Hydrogen", "Helium"], 2, "Hydrogen makes up about 75 percent of the ordinary matter in the universe by mass.", "Helium is the second most abundant element, and oxygen is the most abundant in the Earth crust.", [34]),
 (S, "If the force on an object is doubled while its mass stays the same, what happens to its acceleration?", ["It is halved", "It stays the same", "It doubles", "It becomes four times"], 2, "By Newton's second law, F = ma, so a = F / m. Acceleration is directly proportional to force when mass is fixed.", "If the mass is doubled instead, the acceleration halves.", [2035]),
 (S, "What is acceleration?", ["Rate of change of distance", "Rate of change of velocity", "Rate of change of mass", "Rate of change of force"], 1, "Acceleration is how fast the velocity of an object changes with time, a = change in velocity / time.", "The SI unit of acceleration is metre per second squared.", [2880]),
 (S, "In which year were the Geneva Accords on Afghanistan signed, leading to the Soviet troop withdrawal?", ["1979", "1988", "1992", "2001"], 1, "The Geneva Accords were signed on 14 April 1988 by Pakistan, Afghanistan, the USA and the USSR.", "Soviet forces completed their withdrawal from Afghanistan in February 1989.", [2330, 3664]),
 (S, "Which word is a synonym of accuse?", ["Praise", "Blame", "Defend", "Reward"], 1, "To accuse is to charge someone with a fault or crime, which means to blame.", "A related noun is accusation.", [3377, 4364]),
 (S, "On which date was the Simla Agreement signed between Zulfikar Ali Bhutto and Indira Gandhi?", ["2 July 1972", "3 July 1971", "10 April 1973", "14 August 1972"], 0, "The Simla Agreement was signed on 2 July 1972 after the 1971 war.", "It committed both countries to settle disputes bilaterally and set the Line of Control.", [3082]),
 (S, "What is the additive identity of 5?", ["1", "0", "-5", "5"], 1, "The additive identity is the number which leaves a number unchanged when added. 5 + 0 = 5.", "The multiplicative identity is 1.", [2964]),
 (S, "What is the additive inverse of 65?", ["65", "1/65", "-65", "0"], 2, "The additive inverse is the number which gives zero when added. 65 + (-65) = 0.", "The multiplicative inverse of 65 is 1/65.", [2965]),
 (S, "On which date was the 1973 Constitution of Pakistan adopted by the National Assembly?", ["14 August 1973", "10 April 1973", "23 March 1973", "12 April 1973"], 1, "The National Assembly adopted the Constitution on 10 April 1973. It was enforced later, on 14 August 1973.", "The Constitution was framed under Prime Minister Zulfikar Ali Bhutto.", [2483]),
 (S, "Which system of government was adopted in the 1956 Constitution of Pakistan?", ["Presidential", "Parliamentary", "Military", "Unitary monarchy"], 1, "The 1956 Constitution created a parliamentary federal system with a one-house legislature.", "The 1962 Constitution changed this to a presidential system.", [3483]),
]
